#!/usr/bin/env python3
"""Separate radial projection accuracy from errors generated by time stepping."""
import json
from pathlib import Path
import sys
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parent.parent/'nonlinear_evolution_2026'))
from evolve import Evolution


if __name__=='__main__':
    for points in (65,129,257,513):
        system=Evolution(.02,.3,points,3.,.01,1e-6)
        state=system.initial.copy();r=system.r;profile=np.exp(-(r/.3)**2)
        state[1]+=1e-4*r*r*profile
        state[4]-=2e-5*r*r*profile
        state[5]=5e-4*r*profile
        state[6]=1e-4*r*profile
        f=system.fields(0.,state)
        mask=(r>2*system.dr)&(r<3-2*system.dr)
        print(json.dumps(dict(points=points,constraints=np.max(abs(f['constraints'][mask]),axis=0).tolist(),
                              max_lapse_residual=float(max(abs(f['lapse_residual'][mask]))))),flush=True)
